#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

void insertEnd(Node** headRef, int newData) {
    Node* newNode = new Node();
    newNode->data = newData;
    if (*headRef == nullptr) {
        newNode->next = newNode;
        *headRef = newNode;
        return;
    }
    Node* last = *headRef;
    while (last->next != *headRef) {
        last = last->next;
    }
    last->next = newNode;
    newNode->next = *headRef;
}

void printCircle(Node* head) {
    if (head == nullptr) {
        return;
    }
    Node* cur = head;
    do {
        cout << cur->data << " ";
        cur = cur->next;
    } while (cur != head);
    cout << "(back to " << head->data << ")" << endl;
}

void freeCircle(Node* head) {
    Node* cur = head->next;
    while (cur != head) {
        Node* old = cur;
        cur = cur->next;
        delete old;
    }
    delete head;
}

int main() {
    Node* head = nullptr;
    insertEnd(&head, 1);
    insertEnd(&head, 2);
    insertEnd(&head, 3);
    printCircle(head);
    freeCircle(head);
    return 0;
}
